css:
.nutstd{
  --paper:#f9f7ef;--paper2:#f1ede1;--panel:#fffdf7;--ink:#171913;--muted:#5f6358;--line:#d8d3c4;
  --green:#2f7b43;--orange:#db8b1f;--red:#a55445;--gold:#937224;--dark:#1b1f18;--soft:#f2eee3;
  --shadow:0 12px 30px rgba(18,22,14,.06);
}
.nutstd, .nutstd *{box-sizing:border-box}
.nutstd{scroll-behavior:smooth}
.nutstd{background:var(--paper);color:var(--ink);font-family:ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;line-height:1.45}
.nutstd a{color:inherit;text-decoration-color:#b9b29f;text-underline-offset:3px}
.nutstd a:hover{text-decoration-color:var(--orange)}
.nutstd .page{max-width:1220px;margin:0 auto;padding:20px 24px 84px}
.nutstd .topbar{display:flex;justify-content:space-between;align-items:center;gap:16px;border-bottom:1px solid var(--line);padding-bottom:14px;font-size:11px;letter-spacing:.13em;text-transform:uppercase}
.nutstd .brand{font-weight:900}
.nutstd .brand b{color:var(--orange)}
.nutstd .nav{display:flex;gap:14px;color:var(--muted);flex-wrap:wrap}
.nutstd .kicker, .nutstd .eyebrow{font-size:11px;letter-spacing:.16em;text-transform:uppercase;font-weight:900;color:var(--green)}
.nutstd h1, .nutstd h2, .nutstd h3, .nutstd h4, .nutstd .serif{font-family:Georgia,"Times New Roman",serif;font-weight:500}
.nutstd h1{font-size:clamp(60px,9.2vw,126px);line-height:.84;letter-spacing:-.06em;margin:14px 0 18px}
.nutstd h2{font-size:clamp(40px,5vw,66px);line-height:.96;letter-spacing:-.05em;margin:0}
.nutstd h3{font-size:33px;line-height:1.02;letter-spacing:-.04em;margin:0}
.nutstd h4{font-size:23px;line-height:1.08;letter-spacing:-.03em;margin:0}
.nutstd .hero{padding:60px 0 42px;border-bottom:1px solid var(--line);display:block}
.nutstd .hero .chart-card{margin-top:28px;max-width:100%}
.nutstd .hero-copy{font-family:Georgia,"Times New Roman",serif;font-size:clamp(29px,3.2vw,48px);line-height:1.05;margin:0 0 14px;max-width:720px}
.nutstd .hero-copy .accent{color:var(--orange)}
.nutstd .hero-sub{font-size:18px;max-width:690px;color:#373a32;margin:0 0 22px}
.nutstd .hero-mini{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;max-width:780px}
.nutstd .mini{background:var(--panel);border:1px solid var(--line);border-radius:20px;padding:15px 16px;box-shadow:var(--shadow)}
.nutstd .mini .t{font-size:11px;letter-spacing:.12em;text-transform:uppercase;font-weight:900;color:#55594f}
.nutstd .mini .v{font-family:Georgia,"Times New Roman",serif;font-size:18px;line-height:1.1;margin:7px 0 4px}
.nutstd .mini p{margin:0;font-size:12px;color:var(--muted)}
.nutstd .chart-card{background:var(--panel);border:1px solid var(--line);border-radius:26px;padding:18px 20px;box-shadow:var(--shadow)}
.nutstd .chart-title{display:flex;justify-content:space-between;gap:16px;align-items:end}
.nutstd .chart-title h4{font-size:22px}
.nutstd .chart-title p{margin:7px 0 0;color:var(--muted);font-size:12px;max-width:560px}
.nutstd .legend{display:flex;gap:18px;align-items:center;flex-wrap:wrap;font-size:11px;color:#54584d;margin:10px 0 8px}
.nutstd .dot{width:10px;height:10px;border-radius:50%;display:inline-block;margin-right:7px;vertical-align:middle}
.nutstd .orange{background:var(--orange)}
.nutstd .green{background:var(--green)}
.nutstd .gray{background:#8c8d87}
.nutstd .svg-wrap{width:100%;overflow:hidden}
.nutstd .svg-wrap svg{width:100%;height:auto;display:block}
.nutstd .top-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:12px}
.nutstd .stat{background:var(--soft);border:1px solid #ebe4d3;border-radius:18px;padding:14px}
.nutstd .stat .n{font-family:Georgia,"Times New Roman",serif;font-size:34px;line-height:1}
.nutstd .stat .l{font-size:11px;font-weight:900;letter-spacing:.11em;text-transform:uppercase;color:#66695f;margin-top:5px}
.nutstd .stat p{margin:6px 0 0;font-size:12px;color:var(--muted)}
.nutstd section{padding:58px 0;border-bottom:1px solid var(--line)}
.nutstd .section-head{display:grid;grid-template-columns:.48fr 1.52fr;gap:24px;align-items:start;margin-bottom:26px}
.nutstd .lede{font-family:Georgia,"Times New Roman",serif;font-size:23px;line-height:1.18;color:#353830;margin:13px 0 0;max-width:860px}
.nutstd .plain{font-size:14px;color:#4d5047;max-width:900px;margin:10px 0 0}
.nutstd .cards-3, .nutstd .cards-4{display:grid;gap:14px}
.nutstd .cards-3{grid-template-columns:repeat(3,1fr)}
.nutstd .cards-4{grid-template-columns:repeat(4,1fr)}
.nutstd .card{background:var(--panel);border:1px solid var(--line);border-radius:24px;padding:20px;box-shadow:var(--shadow)}
.nutstd .card p{margin:9px 0 0;font-size:13px;color:#4b4f45}
.nutstd .label{font-size:11px;letter-spacing:.12em;text-transform:uppercase;font-weight:900;color:#64685e}
.nutstd .big{font-family:Georgia,"Times New Roman",serif;font-size:44px;line-height:1.02;letter-spacing:-.05em;margin:8px 0 0}
.nutstd .source-row, .nutstd .sources-inline{margin-top:10px;font-size:10px;color:var(--muted);display:flex;flex-wrap:wrap;gap:10px}
.nutstd .src{font-size:10px;font-weight:900;color:var(--green);white-space:nowrap}
.nutstd .src::after{content:" ↗"}
.nutstd .rulers{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.nutstd .ruler-card{background:var(--panel);border:1px solid var(--line);border-radius:24px;padding:20px}
.nutstd .ruler-card .big-word{font-family:Georgia,"Times New Roman",serif;font-size:28px;line-height:1.02;margin-top:6px}
.nutstd .ruler-card p{margin:8px 0 0;font-size:13px;color:#4f5348}
.nutstd .selector{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 16px}
.nutstd .nut-btn{appearance:none;border:1px solid var(--line);background:var(--panel);border-radius:999px;padding:10px 14px;font:inherit;font-size:13px;cursor:pointer;box-shadow:var(--shadow)}
.nutstd .nut-btn.active{background:var(--dark);border-color:var(--dark);color:var(--paper)}
.nutstd .standard-panel{background:var(--panel);border:1px solid var(--line);border-radius:26px;padding:20px 22px;display:grid;grid-template-columns:1.25fr .75fr;gap:16px;margin-bottom:16px;box-shadow:var(--shadow)}
.nutstd .std-name{font-family:Georgia,"Times New Roman",serif;font-size:28px;line-height:1.06}
.nutstd .std-note{font-size:12px;color:var(--muted);margin-top:6px}
.nutstd .std-price{text-align:right}
.nutstd .std-price .price{font-family:Georgia,"Times New Roman",serif;font-size:58px;line-height:.95}
.nutstd .std-price .sub{font-size:14px;color:var(--muted)}
.nutstd .calc-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.nutstd .calc-card{background:var(--panel);border:1px solid var(--line);border-radius:22px;padding:18px;box-shadow:var(--shadow);min-height:180px}
.nutstd .calc-card .title{display:flex;justify-content:space-between;gap:10px;align-items:start}
.nutstd .calc-card .title span{font-size:11px;letter-spacing:.12em;text-transform:uppercase;font-weight:900;color:#63675d}
.nutstd .calc-card .asset{font-size:20px}
.nutstd .calc-card .qty{font-family:Georgia,"Times New Roman",serif;font-size:52px;line-height:.92;letter-spacing:-.05em;margin:14px 0 2px}
.nutstd .calc-card .unit{font-size:16px}
.nutstd .calc-card .under{font-size:12px;color:var(--muted)}
.nutstd .emoji-line{font-size:24px;line-height:1.2;margin-top:16px;word-break:break-word}
.nutstd .note-band{margin-top:14px;padding:12px 14px;border-left:3px solid var(--orange);background:#f6f1e5;font-size:12px;color:#4a4e44}
.nutstd .bars-card{background:var(--panel);border:1px solid var(--line);border-radius:24px;padding:20px;box-shadow:var(--shadow)}
.nutstd .bar-row{display:grid;grid-template-columns:112px 1fr 82px 88px;gap:14px;align-items:center;margin:18px 0}
.nutstd .bar-row .name{font-weight:900}
.nutstd .bar-row .track{height:14px;background:#eee9dc;border-radius:99px;overflow:hidden}
.nutstd .bar-row .fill{height:100%;border-radius:99px}
.nutstd .bar-row .value{text-align:right;font-weight:900}
.nutstd .bar-row .delta{text-align:right;font-size:12px;color:var(--muted)}
.nutstd .table-wrap{background:var(--panel);border:1px solid var(--line);border-radius:24px;overflow:auto;box-shadow:var(--shadow)}
.nutstd table{width:100%;border-collapse:collapse;min-width:720px}
.nutstd th, .nutstd td{padding:15px 16px;border-bottom:1px solid #ece7d9;text-align:left;vertical-align:top}
.nutstd th{font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:#64685d}
.nutstd td strong{font-size:18px}
.nutstd .basis{font-size:12px;color:var(--muted)}
.nutstd .snapshot-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
.nutstd .snapshot{background:var(--panel);border:1px solid var(--line);border-radius:24px;padding:20px;box-shadow:var(--shadow)}
.nutstd .snap-head{display:flex;justify-content:space-between;gap:12px;align-items:start}
.nutstd .snap-years{display:grid;grid-template-columns:1fr auto 1fr;gap:14px;align-items:center;margin-top:14px}
.nutstd .snap-block .year{font-size:11px;letter-spacing:.12em;text-transform:uppercase;font-weight:900;color:#66685f}
.nutstd .snap-block .lbs{font-family:Georgia,"Times New Roman",serif;font-size:54px;line-height:.92;letter-spacing:-.05em;margin:10px 0 2px}
.nutstd .snap-block .lbs small{font-size:18px}
.nutstd .snap-foot{margin-top:14px;padding-top:14px;border-top:1px solid var(--line);font-size:13px;color:#4d5046}
.nutstd .compare-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.nutstd .compare-card{background:var(--panel);border:1px solid var(--line);border-radius:24px;padding:20px;box-shadow:var(--shadow)}
.nutstd .compare-card .subhead{display:inline-block;background:#f2e1dd;color:#995247;padding:5px 10px;border-radius:999px;font-size:11px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}
.nutstd .compare-card .period{font-family:Georgia,"Times New Roman",serif;font-size:40px;line-height:1;letter-spacing:-.04em;margin:14px 0 12px}
.nutstd .metric-line{display:grid;grid-template-columns:72px 1fr 62px;gap:10px;align-items:center;margin:12px 0}
.nutstd .metric-line .track{height:12px;background:#eee9dc;border-radius:99px;overflow:hidden}
.nutstd .metric-line .fill{height:100%;border-radius:99px}
.nutstd .metric-line .name{font-size:12px;font-weight:900}
.nutstd .metric-line .val{text-align:right;font-size:12px;font-weight:900}
.nutstd .compare-card p{font-size:13px;color:#4d5147;margin:12px 0 0}
.nutstd .triad{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.nutstd .tri-card{background:var(--panel);border:1px solid var(--line);border-radius:24px;padding:20px;box-shadow:var(--shadow)}
.nutstd .tri-card .icon{font-size:28px}
.nutstd .tri-card h4{margin-top:10px}
.nutstd .tri-card p{margin:10px 0 0;font-size:13px;color:#4f5248}
.nutstd .tri-note{margin-top:12px;background:#f4efe3;border-left:3px solid var(--orange);padding:13px 15px;font-size:13px;color:#4d4f45}
.nutstd .grower-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
.nutstd .grower-card{background:var(--panel);border:1px solid var(--line);border-radius:26px;padding:20px;box-shadow:var(--shadow)}
.nutstd .pill-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:14px}
.nutstd .pill{background:var(--soft);border-radius:18px;padding:15px}
.nutstd .pill .num{font-family:Georgia,"Times New Roman",serif;font-size:24px;line-height:1}
.nutstd .pill .desc{font-size:12px;color:var(--muted);margin-top:5px}
.nutstd .acre-boxes{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
.nutstd .acre-stat{background:var(--panel);border:1px solid var(--line);border-radius:22px;padding:18px;box-shadow:var(--shadow);min-height:160px}
.nutstd .acre-stat .icon{font-size:22px}
.nutstd .acre-stat .num{font-family:Georgia,"Times New Roman",serif;font-size:46px;line-height:.96;letter-spacing:-.05em;margin:12px 0 8px}
.nutstd .acre-stat .ttl{font-size:12px;letter-spacing:.12em;text-transform:uppercase;font-weight:900}
.nutstd .acre-stat p{font-size:12px;color:var(--muted);margin:8px 0 0}
.nutstd .history-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
.nutstd .history-card{background:var(--panel);border:1px solid var(--line);border-radius:24px;padding:20px;box-shadow:var(--shadow)}
.nutstd .history-card .row{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:16px}
.nutstd .history-card .yr{font-size:10px;letter-spacing:.12em;text-transform:uppercase;font-weight:900;color:#66695f}
.nutstd .history-card .pr{font-family:Georgia,"Times New Roman",serif;font-size:18px;line-height:1.02;margin-top:5px}
.nutstd .history-card .unit{font-size:10px;color:var(--muted)}
.nutstd .mass-card{background:var(--panel);border:1px solid var(--line);border-radius:26px;padding:20px;box-shadow:var(--shadow)}
.nutstd .mass-bar{display:flex;height:42px;border-radius:16px;overflow:hidden;margin:16px 0 12px;background:#eee8d8;border:1px solid #e5ddc8}
.nutstd .mass-1{background:#d9c79f;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:13px}
.nutstd .mass-2{background:#ebb95a;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:13px}
.nutstd .mass-3{background:#b99762;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:13px;color:#fff}
.nutstd .mass-notes{display:grid;grid-template-columns:120px 1fr;gap:8px 14px;align-items:start;font-size:13px;color:#44483f}
.nutstd .mass-notes b{display:block;font-size:28px;font-family:Georgia,"Times New Roman",serif;font-weight:500}
.nutstd .bee-card{margin-top:16px;background:#faf5e8;border:1px solid #e8dcc0;border-radius:24px;padding:20px}
.nutstd .bee-flow{display:grid;grid-template-columns:1fr auto 1fr;gap:16px;align-items:center;margin-top:14px}
.nutstd .bee-node{background:var(--panel);border:1px solid var(--line);border-radius:20px;padding:16px;text-align:center}
.nutstd .bee-arrow{font-size:28px;color:var(--orange)}
.nutstd .bee-money{font-family:Georgia,"Times New Roman",serif;font-size:48px;line-height:1;margin-top:16px}
.nutstd .balance-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}
.nutstd .bal{background:var(--panel);border:1px solid var(--line);border-radius:22px;padding:18px;box-shadow:var(--shadow)}
.nutstd .bal .icon{font-size:24px}
.nutstd .bal h4{margin:8px 0 8px}
.nutstd .bal p{margin:0;font-size:13px;color:#4e5147}
.nutstd .poster-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.nutstd .poster{background:#fbf7ea;border:3px solid #303328;border-radius:4px;padding:14px;box-shadow:var(--shadow)}
.nutstd .poster .poster-k{display:inline-block;border:1px solid #242821;padding:3px 8px;font-size:11px;letter-spacing:.08em;text-transform:uppercase;font-weight:900;background:#fff}
.nutstd .poster .poster-h{font-family:Georgia,"Times New Roman",serif;font-size:38px;line-height:.92;letter-spacing:-.05em;margin:10px 0 12px}
.nutstd .poster .poster-sub{font-size:12px;color:#575a4f;margin-bottom:12px}
.nutstd .poster-grid-4{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.nutstd .poster-box{background:#fff;border:1px solid #3b4035;padding:10px;text-align:center}
.nutstd .poster-box .y{font-size:12px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}
.nutstd .poster-box .p{font-size:12px;color:var(--muted);margin-top:6px}
.nutstd .poster-box .q{font-family:Georgia,"Times New Roman",serif;font-size:22px;line-height:1;margin-top:8px}
.nutstd .poster-box .e{font-size:18px;line-height:1.15;min-height:72px;display:flex;align-items:center;justify-content:center}
.nutstd .quote-final{padding:64px 0 0}
.nutstd .quote-box{font-family:Georgia,"Times New Roman",serif;font-size:clamp(34px,5vw,60px);line-height:1.04;letter-spacing:-.05em}
.nutstd .quote-box .g{color:var(--green)}
.nutstd .quote-box .o{color:var(--orange)}
.nutstd .foot{display:flex;justify-content:space-between;gap:20px;margin-top:34px;padding-top:16px;border-top:1px solid var(--line);font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}
@media (max-width:1100px){.nutstd .hero, .nutstd .section-head, .nutstd .standard-panel, .nutstd .cards-3, .nutstd .cards-4, .nutstd .rulers, .nutstd .calc-grid, .nutstd .compare-grid, .nutstd .triad, .nutstd .grower-grid, .nutstd .acre-boxes, .nutstd .history-grid, .nutstd .balance-grid, .nutstd .poster-grid, .nutstd .snapshot-grid, .nutstd .basket-split, .nutstd .top-grid, .nutstd .bee-flow, .nutstd .hero-mini, .nutstd .species-top, .nutstd .land-grid, .nutstd .bars-split, .nutstd .same-clock, .nutstd .history-card .row{grid-template-columns:1fr!important}
.nutstd .hero-mini, .nutstd .top-grid, .nutstd .calc-grid, .nutstd .compare-grid, .nutstd .triad, .nutstd .grower-grid, .nutstd .acre-boxes, .nutstd .history-grid, .nutstd .balance-grid, .nutstd .poster-grid, .nutstd .snapshot-grid, .nutstd .cards-3, .nutstd .cards-4, .nutstd .rulers{display:grid}
.nutstd .bar-row{grid-template-columns:96px 1fr 74px 72px}
.nutstd .poster-grid-4{grid-template-columns:repeat(2,1fr)}}
@media (max-width:740px){.nutstd .page{padding:16px 14px 70px}
.nutstd .hero{padding-top:34px}
.nutstd .topbar{align-items:flex-start;flex-direction:column}
.nutstd .calc-card .qty, .nutstd .big, .nutstd .hero-number, .nutstd .std-price .price{font-size:42px}
.nutstd .poster-grid-4{grid-template-columns:1fr 1fr}
.nutstd .hero-mini{grid-template-columns:1fr}
.nutstd .bar-row{grid-template-columns:86px 1fr 64px 60px;gap:8px}
.nutstd .mass-notes{grid-template-columns:1fr}
.nutstd .bee-flow{grid-template-columns:1fr}}

