function fmtMoney(n){return '$'+(n<1?n.toFixed(3):n.toFixed(2))}
function fmtQty(n){if(n>=10000)return n.toLocaleString(undefined,{maximumFractionDigits:0});if(n>=1000)return n.toLocaleString(undefined,{maximumFractionDigits:1});if(n>=100)return n.toLocaleString(undefined,{maximumFractionDigits:1});if(n>=10)return n.toLocaleString(undefined,{maximumFractionDigits:2});return n.toLocaleString(undefined,{maximumFractionDigits:3})}
function emojiPile(emoji,q){const count=Math.max(3,Math.min(16,Math.round(Math.log10(q+1)*4.4)));return '🧺'+emoji.repeat(count)}
function renderSelector(){
