function lineChart(elId, series, opts={}){
  const width=660, height=290, pad={t:20,r:48,b:30,l:42};
  const xmin=0, xmax=series[0].points.length-1;
  let ymin=Infinity,ymax=-Infinity;
  series.forEach(s=>s.points.forEach(v=>{ymin=Math.min(ymin,v);ymax=Math.max(ymax,v)}));
  ymin=Math.floor(ymin/10)*10; ymax=Math.ceil(ymax/10)*10;
  const x=i=>pad.l+(i-xmin)/(xmax-xmin)*(width-pad.l-pad.r);
  const y=v=>height-pad.b-(v-ymin)/(ymax-ymin)*(height-pad.t-pad.b);
  const grid=[];
  for(let g=ymin; g<=ymax; g+=20){grid.push(`<line x1="${pad.l}" y1="${y(g)}" x2="${width-pad.r}" y2="${y(g)}" stroke="#e8e2d3" stroke-width="1"/><text x="${pad.l-8}" y="${y(g)+4}" text-anchor="end" font-size="10" fill="#74786d">${g}</text>`)}
  const years=opts.labels||[];
  const labels=years.map((yr,i)=>`<text x="${x(i)}" y="${height-10}" text-anchor="middle" font-size="10" fill="#74786d">${yr}</text>`).join('');
  const paths=series.map(s=>{
    const d=s.points.map((v,i)=>`${i===0?'M':'L'} ${x(i)} ${y(v)}`).join(' ');
    const pts=s.points.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="${s.color}" stroke="#fff6"/>`).join('');
    const last=s.points[s.points.length-1];
    return `<path d="${d}" fill="none" stroke="${s.color}" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" ${s.dashed?'stroke-dasharray="8 6"':''}/>${pts}<text x="${width-pad.r+6}" y="${y(last)+4}" font-size="11" font-weight="900" fill="${s.color}">${s.name} ${last}</text>`;
  }).join('');
  document.getElementById(elId).innerHTML=`<svg viewBox="0 0 ${width} ${height}" aria-label="chart"><rect x="0" y="0" width="${width}" height="${height}" fill="transparent"/>${grid.join('')}<line x1="${pad.l}" y1="${height-pad.b}" x2="${width-pad.r}" y2="${height-pad.b}" stroke="#6e7368" stroke-width="1.4"/><line x1="${pad.l}" y1="${pad.t}" x2="${pad.l}" y2="${height-pad.b}" stroke="#6e7368" stroke-width="1.4"/>${labels}${paths}</svg>`;
}
